// Tests for the back-side logic. Run: npm test (Node 18+).
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createMachine, checkNorm, checkPanel, STATUS, DEST, OPEN_QUESTION } from '../src/engine.js';
import { CELLS, CREW, realPeople } from '../src/config.js';
import { INSPIRATION4 } from '../src/inspiration4.js';

const PEOPLE = [...CREW, ...realPeople(INSPIRATION4.subjects)];
const TOM = 'crew-1';
const ELLY = 'crew-2';

const fixedNow = () => new Date('2026-11-14T18:40:00Z');
const make = (state, crew = PEOPLE) => createMachine({ cells: CELLS, crew, state, now: fixedNow });
const codes = (entry) => entry.steps.map((s) => s.code);
const r = (indicator, value, person = TOM, source = indicator) => ({ person, source, indicator, value });
const pulse = (v) => r('pulse', v);
const bp = (sys, dia) => r('bp', { sys, dia });
const camera = (v) => r('camera', v);
const xray = (v = 'image') => r('xray', v);

test('number within the norm: stays in the machine, the AI is not triggered', () => {
  const e = make().receive(pulse(72));
  assert.equal(e.status, STATUS.OK);
  assert.equal(e.dest, DEST.NONE);
  assert.ok(e.steps.every((s) => s.by !== 'ai'));
  assert.equal(e.cellId, 'A');
  assert.equal(e.steps[0].code, 'norm-used');
  assert.equal(e.steps[0].norm, 'earthGeneral');
  assert.equal(e.steps[0].question, OPEN_QUESTION.WHICH_NORM);
});

test('number outside the norm: the AI is triggered and takes over, open questions 1 and 2 shown', () => {
  const e = make().receive(pulse(128));
  assert.equal(e.status, STATUS.OUT);
  assert.equal(e.dest, DEST.AI);
  assert.deepEqual(codes(e), ['norm-used', 'out-of-norm', 'ai-takes', 'ai-next-open', 'direct-alarm-open']);
  assert.equal(e.steps[1].side, 'above');
});

test('pulse norm edges: 60 and 100 are within, 59 and 101 are outside', () => {
  const m = make();
  assert.equal(m.receive(pulse(60)).status, STATUS.OK);
  assert.equal(m.receive(pulse(100)).status, STATUS.OK);
  assert.equal(m.receive(pulse(59)).steps[1].side, 'below');
  assert.equal(m.receive(pulse(101)).status, STATUS.OUT);
});

test('blood pressure: below 120 and 80, no lower limit shown, impossible numbers rejected', () => {
  const m = make();
  const ok = m.receive(bp(118, 76));
  assert.deepEqual(codes(ok), ['norm-used', 'in-norm', 'no-lower-limit']);
  assert.equal(m.receive(bp(120, 70)).status, STATUS.OUT);
  assert.equal(m.receive(bp(119, 80)).status, STATUS.OUT);
  for (const v of [[0, 0], [-10, -5], [null, null], ['', '']]) {
    assert.equal(m.receive(bp(...v)).status, STATUS.UNKNOWN, JSON.stringify(v));
  }
  assert.equal(m.receive(bp('118', '76')).status, STATUS.OK);
});

test('fasting sugar, body temperature, oxygen: edges', () => {
  const m = make();
  assert.equal(m.receive(r('glucose', 70)).status, STATUS.OK);
  assert.equal(m.receive(r('glucose', 100)).status, STATUS.OUT);
  assert.equal(m.receive(r('temp', 36.1)).status, STATUS.OK);
  assert.equal(m.receive(r('temp', 37.3)).status, STATUS.OUT);
  assert.equal(m.receive(r('spo2', 95)).status, STATUS.OK);
  assert.equal(m.receive(r('spo2', 94)).status, STATUS.OUT);
});

test('sleep has only a lower limit; radiation limit is strictly below 600', () => {
  const m = make();
  assert.equal(m.receive(r('sleep', 7)).status, STATUS.OK);
  assert.equal(m.receive(r('sleep', 12)).status, STATUS.OK);
  assert.equal(m.receive(r('sleep', 6.9)).steps[1].side, 'below');
  assert.equal(m.receive(r('radiation', 599)).status, STATUS.OK);
  const at = m.receive(r('radiation', 600));
  assert.equal(at.status, STATUS.OUT);
  assert.equal(at.steps[0].norm, 'spaceGeneral');
});

test('cabin CO2 and temperature use NASA standard limits', () => {
  const m = make();
  assert.equal(m.receive(r('co2', 3)).status, STATUS.OK);
  assert.equal(m.receive(r('co2', 3.1)).status, STATUS.OUT);
  assert.equal(m.receive(r('cabinTemp', 18)).status, STATUS.OK);
  assert.equal(m.receive(r('cabinTemp', 27.5)).status, STATUS.OUT);
});

test('fitness and strength: NASA rule of at least 80% of the person\'s own pre-flight level', () => {
  const m = make();
  const ok = m.receive(r('vo2max', 34)); // Tom: above 80% of 42
  assert.equal(ok.status, STATUS.OK);
  assert.ok(ok.steps[1].percent >= 80);
  assert.equal(ok.steps[0].norm, 'personalEarth');
  const low = m.receive(r('vo2max', 33)); // Tom: below 80% of 42
  assert.equal(low.status, STATUS.OUT);
  assert.equal(low.dest, DEST.AI);
  assert.equal(m.receive(r('strength', 120)).status, STATUS.OK); // 80% of 150
  assert.equal(m.receive(r('strength', 119)).status, STATUS.OUT);
});

test('without a pre-flight level the personal norm cannot be checked', () => {
  const e = make().receive(r('vo2max', 38, 'i4-c001')); // a real Inspiration4 participant has no pre-flight fitness level here
  assert.equal(e.status, STATUS.UNKNOWN);
  assert.deepEqual(codes(e), ['no-baseline']);
});

test('bone density: both sites must reach their NASA minimum', () => {
  const m = make();
  assert.equal(m.receive(r('bone', { hipSpine: 97, neck: 93 })).status, STATUS.OK);
  assert.equal(m.receive(r('bone', { hipSpine: 94, neck: 95 })).status, STATUS.OUT);
  assert.equal(m.receive(r('bone', { hipSpine: 96, neck: 89 })).status, STATUS.OUT);
  assert.equal(m.receive(r('bone', { hipSpine: 96 })).status, STATUS.UNKNOWN);
});

test('blood panel: real Inspiration4 data, each value against its own lab range', () => {
  const m = make();
  const ok = m.receive(r('blood', { subject: 'X', timepoint: 'T', analytes: [
    { name: 'a', value: 5, min: 1, max: 10, units: 'u' },
    { name: 'b', value: 80, min: 60, max: null, units: 'u' },
  ] }));
  assert.equal(ok.status, STATUS.OK);
  assert.deepEqual(codes(ok), ['norm-used', 'panel-in-norm']);
  const out = m.receive(r('blood', { analytes: [{ name: 'a', value: 11, min: 1, max: 10, units: 'u' }, { name: 'b', value: 0.5, min: 1, max: 10 }] }));
  assert.equal(out.status, STATUS.OUT);
  assert.equal(out.dest, DEST.AI);
  assert.equal(out.steps[1].out.length, 2);
  assert.equal(m.receive(r('blood', { analytes: [{ name: 'a', value: 'NA', min: 1, max: 2 }] })).status, STATUS.UNKNOWN);
  assert.equal(m.receive(r('blood', null)).status, STATUS.UNKNOWN);
  // Every real panel in the NASA data can be checked.
  for (const [subject, s] of Object.entries(INSPIRATION4.subjects)) {
    for (const [tp, analytes] of Object.entries(s.panels)) {
      const res = checkPanel({ analytes });
      assert.ok(res.valid, `${subject} ${tp}`);
      assert.ok(res.checked >= 30, `${subject} ${tp} checked ${res.checked}`);
    }
  }
});

test('AI down: an out-of-norm number is not guessed, it is an open question', () => {
  const e = make({ aiWorks: false }).receive(pulse(128));
  assert.equal(e.dest, DEST.UNDECIDED);
  assert.deepEqual(codes(e), ['norm-used', 'out-of-norm', 'ai-down-open', 'direct-alarm-open']);
});

test('complex data: AI takes it when it works, open question when it is down', () => {
  const up = make().receive(xray());
  assert.equal(up.dest, DEST.AI);
  assert.deepEqual(codes(up), ['needs-analysis', 'ai-analyzes', 'complex-who-open']);
  for (const state of [{ aiWorks: false, doctorOnBoard: true }, { aiWorks: false, linkToEarth: false }]) {
    const down = make(state).receive(xray());
    assert.equal(down.dest, DEST.UNDECIDED);
    assert.deepEqual(codes(down), ['needs-analysis', 'ai-down-open']);
  }
  assert.equal(make().receive(xray(null)).status, STATUS.UNKNOWN);
});

test('camera: sleep ignored; chest grab calls the doctor on board, else on Earth, else open', () => {
  assert.equal(make().receive(camera('sleeping')).status, STATUS.IGNORED);
  assert.equal(make({ doctorOnBoard: true }).receive(camera('chest_grab')).dest, DEST.DOCTOR_ONBOARD);
  const earth = make({ doctorOnBoard: false, linkToEarth: true }).receive(camera('chest_grab'));
  assert.equal(earth.dest, DEST.DOCTOR_EARTH);
  assert.ok(earth.steps.every((s) => s.by !== 'ai'));
  const alone = make({ doctorOnBoard: false, linkToEarth: false }).receive(camera('chest_grab'));
  assert.equal(alone.dest, DEST.UNDECIDED);
  for (const v of ['constructor', 'toString', 'dancing', undefined]) {
    assert.equal(make().receive(camera(v)).status, STATUS.UNKNOWN);
  }
});

test('psyche: daily reports are recorded and reviewed by the AI later', () => {
  const m = make();
  const mood = m.receive(r('mood', 'bad'));
  assert.equal(mood.status, STATUS.RECORDED);
  assert.equal(mood.dest, DEST.NONE);
  assert.deepEqual(codes(mood), ['recorded', 'psych-review-later']);
  m.receive(r('attitude', 'sluggish'));
  assert.equal(m.pendingReports(TOM), 2);
  const rev = m.review(TOM);
  assert.equal(rev.dest, DEST.AI);
  assert.equal(rev.person, TOM);
  assert.equal(rev.steps[0].count, 2);
  assert.equal(rev.steps[1].question, OPEN_QUESTION.PSYCH_RULE);
  assert.equal(m.pendingReports(TOM), 0);
  assert.equal(m.review(TOM).steps[0].code, 'review-empty');
});

test('psyche: review with the AI down is an open question and keeps the reports', () => {
  const m = make({ aiWorks: false });
  m.receive(r('mood', 'fair'));
  const rev = m.review(TOM);
  assert.equal(rev.dest, DEST.UNDECIDED);
  assert.equal(m.pendingReports(TOM), 1);
});

test('self-reports without a review rule say there is no threshold', () => {
  const e = make().receive(r('cognition', 'worse than before flight'));
  assert.equal(e.status, STATUS.RECORDED);
  assert.deepEqual(codes(e), ['recorded', 'no-threshold']);
  assert.equal(make().receive(r('sleepQuality', '')).status, STATUS.UNKNOWN);
});

test('unreadable numbers are not guessed and never become 0', () => {
  const m = make();
  for (const v of ['abc', '', ' ', '\t', false, null, undefined, [72], {}, -5, Number.NaN, Infinity]) {
    assert.equal(m.receive(pulse(v)).status, STATUS.UNKNOWN, `pulse ${JSON.stringify(v)}`);
  }
  assert.equal(m.receive(pulse('72')).status, STATUS.OK);
  assert.equal(m.receive({ indicator: 'nothing', value: 1 }).status, STATUS.UNKNOWN);
  assert.equal(m.receive(undefined).status, STATUS.UNKNOWN);
});

test('state switches take effect for the next reading and each entry keeps a snapshot', () => {
  const m = make();
  const first = m.receive(pulse(128));
  m.setState({ aiWorks: false });
  const second = m.receive(pulse(128));
  assert.equal(first.dest, DEST.AI);
  assert.equal(second.dest, DEST.UNDECIDED);
  assert.equal(first.state.aiWorks, true);
  assert.equal(second.id, first.id + 1);
});

test('cabin temperature below zero is a real reading: out of the norm, not unreadable', () => {
  const m = make();
  const frost = m.receive(r('cabinTemp', -1));
  assert.equal(frost.status, STATUS.OUT);
  assert.equal(frost.steps[1].side, 'below');
  assert.equal(m.receive(r('cabinTemp', '-3,5'.replace(',', '.'))).status, STATUS.OUT);
  // Body readings still refuse numbers below zero.
  assert.equal(m.receive(r('temp', -1)).status, STATUS.UNKNOWN);
});

