test('hours of sleep are checked against the norm and also go to the periodic review', () => {
  const m = make();
  const e = m.receive(r('sleep', 6));
  assert.equal(e.status, STATUS.OUT);
  assert.ok(codes(e).includes('psych-review-later'));
  assert.equal(m.pendingReports(TOM), 1);
  m.receive(r('sleep', ''));
  assert.equal(m.pendingReports(TOM), 1, 'an unreadable sleep reading is not put in the pile');
});

test('empty and out-of-scale self-reports are not recorded; an empty review says so', () => {
  const m = make();
  for (const v of ['', '   ', null]) {
    assert.equal(m.receive(r('mood', v)).dest, DEST.UNDECIDED, JSON.stringify(v));
  }
  assert.equal(m.receive(xray('   ')).status, STATUS.UNKNOWN);
  for (const v of [0, 8, 99, 'abc']) {
    assert.equal(m.receive(r('sleepQuality', v)).status, STATUS.UNKNOWN, `sleep quality ${v}`);
  }
  assert.equal(m.receive(r('sleepQuality', 5)).status, STATUS.RECORDED);
  assert.equal(m.pendingReports(TOM), 0);
  const rev = m.review(TOM);
  assert.equal(rev.status, STATUS.EMPTY);
  assert.equal(rev.dest, DEST.NONE);
});

test('more routes: panel out of norm with the AI down, camera alarm with a doctor but no link', () => {
  const out = make({ aiWorks: false }).receive(r('blood', { analytes: [{ name: 'a', value: 11, min: 1, max: 10 }] }));
  assert.equal(out.status, STATUS.OUT);
  assert.equal(out.dest, DEST.UNDECIDED);
  assert.deepEqual(codes(out), ['norm-used', 'panel-out', 'ai-down-open', 'direct-alarm-open']);
  assert.equal(make({ doctorOnBoard: true, linkToEarth: false }).receive(camera('chest_grab')).dest, DEST.DOCTOR_ONBOARD);
});

test('women get the lab ranges for women where the lab gives them', () => {
  const women = Object.entries(INSPIRATION4.subjects).filter(([, s]) => s.sex === 'F');
  const men = Object.entries(INSPIRATION4.subjects).filter(([, s]) => s.sex === 'M');
  assert.ok(women.length > 0 && men.length > 0);
  const tp = Object.keys(women[0][1].panels)[0];
  const range = (panel) => Object.fromEntries(panel.map((a) => [a.code || a.name, `${a.min}-${a.max}`]));
  const f = range(women[0][1].panels[tp]);
  const mm = range(men[0][1].panels[tp]);
  const differ = Object.keys(f).filter((k) => k in mm && f[k] !== mm[k]);
  assert.ok(differ.length > 0, 'at least one analyte has a different range for women');
});

test('every reading must be signed with a known person', () => {
  const m = make();
  for (const reading of [{ indicator: 'pulse', value: 72 }, { person: 'nobody', indicator: 'pulse', value: 72 }]) {
    const e = m.receive(reading);
    assert.equal(e.status, STATUS.UNKNOWN);
    assert.equal(e.dest, DEST.UNDECIDED);
    assert.deepEqual(codes(e), ['no-person']);
  }
  assert.equal(m.review('nobody').status, STATUS.UNKNOWN);
});

test('each person has their own pile, history and pre-flight levels', () => {
  const m = make();
  m.receive(r('mood', 'bad', TOM));
  assert.equal(m.pendingReports(TOM), 1);
  assert.equal(m.pendingReports(ELLY), 0);
  assert.equal(m.review(ELLY).status, STATUS.EMPTY);
  assert.equal(m.pendingReports(TOM), 1, "Elly's review does not touch Tom's pile");
  m.receive(r('pulse', 72, TOM));
  m.receive(r('pulse', 80, TOM));
  assert.equal(m.history(TOM, 'pulse').length, 2);
  assert.equal(m.history(ELLY, 'pulse').length, 0);
  // The same result is in the norm for one person and out of it for another.
  assert.equal(m.receive(r('vo2max', 31, ELLY)).status, STATUS.OK); // Elly: above 80% of 38
  assert.equal(m.receive(r('vo2max', 31, TOM)).status, STATUS.OUT); // Tom: below 80% of 42
});

test('a reading can carry its own time, and history is kept in time order', () => {
  const m = make();
  const later = m.receive({ ...r('pulse', 90), time: '2026-03-02T08:00:00Z' });
  const earlier = m.receive({ ...r('pulse', 70), time: '2026-03-01T08:00:00Z' });
  assert.equal(later.time.toISOString(), '2026-03-02T08:00:00.000Z');
  assert.equal(earlier.person, TOM);
  const h = m.history(TOM, 'pulse');
  assert.deepEqual(h.map((x) => x.value), [70, 90]);
  assert.equal(m.receive({ ...r('pulse', 70), time: 'not a date' }).time.toISOString(), fixedNow().toISOString());
});

test('every cell has a known kind, and every number cell shows which norm it uses', () => {
  for (const c of CELLS) {
    assert.ok(['number', 'panel', 'complex', 'camera', 'self-report'].includes(c.kind), c.indicator);
    if (c.kind === 'number' || c.kind === 'panel') {
      assert.ok(c.norms && c.norms[c.compareWith], `${c.indicator} compares with a norm that has data`);
    }
  }
  assert.deepEqual(checkNorm({ normType: 'other' }, 1), { valid: false });
});
